// quick one-off runner: node uq.mjs '<instanceJson>' ... (schema fixed to {"uniqueItems":true})
import { spawnSync } from 'node:child_process';
const EXE = '/workspace/dataset/test5_executable';
const schema = process.env.SCHEMA || '{"uniqueItems":true}';
for (const a of process.argv.slice(2)) {
  const r = spawnSync(EXE, ['--a', a, '--b', schema], { encoding: 'utf8' });
  console.log(
    a.slice(0, 90).padEnd(90),
    '=>',
    r.status === 0 ? JSON.stringify(r.stdout) : 'EXIT ' + r.status + ' ' + (r.stderr || '').trim().split('\n').slice(-1)[0].slice(0, 120),
  );
}

import { spawnSync } from 'node:child_process';
const EXE = '/workspace/dataset/test5_executable';
const run = (a, b = '{"uniqueItems":true}') => {
  const r = spawnSync(EXE, ['--a', a, '--b', b], { encoding: 'utf8' });
  return r.status === 0 ? r.stdout.trim() : 'EXIT' + r.status;
};
// position scan: base ascending array of length n with a duplicate pair, insert NaN at each position
const mode = process.argv[2];
if (mode === 'scan') {
  const n = Number(process.argv[3] || 10);
  const base = [];
  for (let i = 0; i < n; i++) base.push(i % 2 === 0 ? i : i - 1); // 0,0,2,2,4,4,...
  for (let p = 0; p <= n; p++) {
    const arr = base.slice();
    arr.splice(p, 0, 'NaN');
    const a = '[' + arr.join(',') + ']';
    console.log(String(p).padStart(3), a.slice(0, 100).padEnd(100), '=>', run(a));
  }
}
if (mode === 'shuf') {
  // descending base with duplicate + NaN at each position
  const n = Number(process.argv[3] || 8);
  const base = [];
  for (let i = n; i > 0; i--) base.push(i);
  base.push(n); // duplicate of first
  for (let p = 0; p <= base.length; p++) {
    const arr = base.slice();
    arr.splice(p, 0, 'NaN');
    const a = '[' + arr.join(',') + ']';
    console.log(String(p).padStart(3), a.slice(0, 100).padEnd(100), '=>', run(a));
  }
}
if (mode === 'big') {
  const n = Number(process.argv[3] || 70);
  const dupAt = Number(process.argv[4] || 0);
  const nanAt = Number(process.argv[5] || 0);
  const arr = [];
  for (let i = 0; i < n; i++) arr.push(i * 2);
  arr[dupAt + 1] = arr[dupAt];
  arr.splice(nanAt, 0, 'NaN');
  const a = '[' + arr.join(',') + ']';
  console.log(`n=${n} dupAt=${dupAt} nanAt=${nanAt}`, '=>', run(a));
}
